import Foundation

// MARK: - Overcoming Anxiety Content Expansion (Entries 9–20)

extension ContentLibrary {

    static let anxietyContentExpansion: [DayContent] = [
        DayContent(
            scriptureReference: "Isaiah 41:10",
            scriptureText: "So do not fear, for I am with you; do not be dismayed, for I am your God. I will strengthen you and help you; I will uphold you with my righteous right hand.",
            devotionalTitle: "Held by His Hand",
            devotionalText: "God doesn't just tell you not to fear — He tells you why. He is with you. He is your God. He will strengthen, help, and uphold you. That's four promises in one verse. Anxiety screams that you're on your own, but God's Word says the opposite. His righteous right hand holds you steady when everything else feels shaky.",
            prayerText: "Lord, I hear Your command not to fear, and I receive Your promises. You are with me. You are my God. You will strengthen me and help me. I rest in Your righteous right hand today. When anxiety rises, remind me of this verse. I am held. I am not alone. In Jesus' name, amen.",
            reflectionPrompt: "Which of God's four promises in this verse do you need most today?",
            actionSteps: ["Write Isaiah 41:10 on a card and carry it with you today", "When anxiety strikes, whisper 'You are with me' until your heart settles"]
        ),
        DayContent(
            scriptureReference: "Psalm 94:19",
            scriptureText: "When anxiety was great within me, your consolation brought me joy.",
            devotionalTitle: "Consolation in the Chaos",
            devotionalText: "The psalmist doesn't pretend anxiety doesn't exist. He names it — great anxiety, overwhelming worry. But he also names the antidote: God's consolation. Not a quick fix, but a deep comfort that transforms anxiety into joy. God doesn't always remove the circumstances that cause anxiety. Instead, He enters them with you and brings consolation that changes everything from the inside.",
            prayerText: "Lord, my anxiety is great within me. I don't hide it from You — You already see it. Bring me Your consolation. Not a quick fix, but a deep, lasting comfort that transforms my fear into joy. Sit with me in this anxious place and let Your presence be enough. In Jesus' name, amen.",
            reflectionPrompt: "When has God's comfort surprised you in the middle of great anxiety?",
            actionSteps: ["Name your anxiety honestly before God — write it out in full detail", "Ask God for His consolation and sit quietly for 5 minutes waiting for His peace"]
        ),
        DayContent(
            scriptureReference: "Matthew 11:28-30",
            scriptureText: "Come to me, all you who are weary and burdened, and I will give you rest. Take my yoke upon you and learn from me, for I am gentle and humble in heart, and you will find rest for your souls.",
            devotionalTitle: "Rest for the Anxious Soul",
            devotionalText: "Jesus extends this invitation to the weary and burdened — that includes the anxious. His yoke isn't another burden to carry; it's a partnership where He does the heavy lifting. 'Learn from me' suggests that rest is something we grow into, not just stumble upon. Jesus is gentle with your anxiety. He doesn't shame it — He invites you to trade it for His rest.",
            prayerText: "Jesus, I come to You weary and burdened. I accept Your invitation to rest. Take the weight of my anxiety and replace it with Your gentle yoke. Teach me to rest — not just physically, but in my soul. I want to learn from You, the One who is gentle and humble in heart. I choose Your rest today. In Jesus' name, amen.",
            reflectionPrompt: "What burden are you carrying that Jesus is inviting you to lay down right now?",
            actionSteps: ["Physically put down whatever you're holding, close your eyes, and say 'I give this to You, Jesus'", "Identify one anxious burden and write it on paper, then place it in your Bible as a symbol of giving it to God"]
        ),
        DayContent(
            scriptureReference: "Psalm 55:22",
            scriptureText: "Cast your cares on the Lord and he will sustain you; he will never let the righteous be shaken.",
            devotionalTitle: "Cast, Don't Carry",
            devotionalText: "The word 'cast' implies force — like throwing a heavy burden off your shoulders. God doesn't want you to gently set your cares down and pick them back up later. He wants you to hurl them at Him with everything you've got. And His promise in return? He will sustain you. Not maybe. Not sometimes. He will sustain you, and you will not be shaken.",
            prayerText: "Lord, I cast my cares on You — all of them, right now. I'm not gently placing them; I'm throwing them because they're too heavy for me. Sustain me today. Keep me from being shaken. I trust that You can carry what I cannot. Every anxious thought, every fearful scenario — I cast it all to You. In Jesus' name, amen.",
            reflectionPrompt: "Are you truly casting your cares or just temporarily setting them down?",
            actionSteps: ["Write your worries on stones and physically throw them into a body of water or open space", "Each time you catch yourself picking up an old worry, say 'I already cast this — it's Yours, Lord'"]
        ),
        DayContent(
            scriptureReference: "2 Timothy 1:7",
            scriptureText: "For the Spirit God gave us does not make us timid, but gives us power, love and self-discipline.",
            devotionalTitle: "The Spirit of Power",
            devotionalText: "Anxiety often produces timidity — a shrinking back from life, from risks, from obedience. But Paul reminds Timothy that God's Spirit produces the opposite: power, love, and self-discipline. If you feel paralyzed by fear, it's not coming from God. He gave you a Spirit that empowers, not one that paralyzes. Today, step forward in the power you've already been given.",
            prayerText: "Lord, I reject the spirit of timidity and receive the Spirit You gave me — one of power, love, and self-discipline. Where anxiety has made me shrink back, empower me to step forward. Where fear has paralyzed me, give me courage to move. Your Spirit in me is greater than any anxiety over me. In Jesus' name, amen.",
            reflectionPrompt: "Where has anxiety made you timid that God's Spirit wants to make you bold?",
            actionSteps: ["Identify one thing anxiety has kept you from doing and take one small step toward it today", "Declare 2 Timothy 1:7 out loud three times as a statement of truth over your life"]
        ),
        DayContent(
            scriptureReference: "Psalm 23:4",
            scriptureText: "Even though I walk through the darkest valley, I will fear no evil, for you are with me; your rod and your staff, they comfort me.",
            devotionalTitle: "Through the Valley",
            devotionalText: "David says 'through' — not 'stuck in.' The valley is a passage, not a permanent address. And even in the darkest part, fear doesn't have to win because God is with you. His rod protects from danger; His staff guides along the path. You're not lost in the dark. You're being shepherded through it by Someone who knows the way out.",
            prayerText: "Lord, even in my darkest valley, I will not fear because You are with me. Your rod and Your staff comfort me. I trust that this valley is not my destination — I'm passing through. Walk with me, guide me, protect me. I choose faith over fear because my Shepherd knows the way. In Jesus' name, amen.",
            reflectionPrompt: "What valley are you walking through right now, and can you trust God to lead you out of it?",
            actionSteps: ["Draw or write Psalm 23:4 and place it somewhere you'll see it when anxiety hits", "Tell someone you trust about the valley you're in and ask them to pray for you"]
        ),
        DayContent(
            scriptureReference: "John 14:27",
            scriptureText: "Peace I leave with you; my peace I give you. I do not give to you as the world gives. Do not let your hearts be troubled and do not be afraid.",
            devotionalTitle: "A Different Kind of Peace",
            devotionalText: "The world's peace depends on circumstances — when things are good, you feel calm. Jesus' peace is fundamentally different. It exists independent of your situation. He gave it to His disciples the night before His crucifixion — the worst possible circumstances. His peace isn't the absence of trouble; it's the presence of God in the middle of it.",
            prayerText: "Jesus, I receive Your peace — not the world's cheap imitation, but the real thing. The peace that exists even when circumstances are terrible. The peace that comes from Your presence, not my situation. Don't let my heart be troubled. Don't let me be afraid. Your peace is my inheritance. I claim it today. In Jesus' name, amen.",
            reflectionPrompt: "How is Jesus' peace different from the peace the world offers you?",
            actionSteps: ["When you feel anxious today, pause and say 'Jesus, I receive Your peace right now'", "Journal about the difference between circumstantial peace and the peace Jesus offers"]
        ),
        DayContent(
            scriptureReference: "1 Peter 5:6-7",
            scriptureText: "Humble yourselves, therefore, under God's mighty hand, that he may lift you up in due time. Cast all your anxiety on him because he cares for you.",
            devotionalTitle: "He Cares for You",
            devotionalText: "Peter connects humility with anxiety relief. Pride says 'I should be able to handle this.' Humility says 'I can't, and that's okay — God can.' Casting your anxiety requires admitting you're not strong enough to carry it. That's not weakness; that's wisdom. The reason you can cast it all on Him is beautifully simple: He cares for you. Not just about you. For you.",
            prayerText: "Lord, I humble myself under Your mighty hand. I admit I can't carry this anxiety alone. I cast all of it on You — every worry, every fear, every worst-case scenario. You care for me. That simple truth changes everything. Lift me up in Your timing. I trust Your mighty hand. In Jesus' name, amen.",
            reflectionPrompt: "Is pride keeping you from admitting you can't handle your anxiety alone?",
            actionSteps: ["Confess to God: 'I can't carry this, and I need Your help'", "Share your anxiety with one trusted person as an act of humility"]
        ),
        DayContent(
            scriptureReference: "Psalm 34:4",
            scriptureText: "I sought the Lord, and he answered me; he delivered me from all my fears.",
            devotionalTitle: "Delivered From All Fears",
            devotionalText: "David doesn't say God delivered him from some fears, or the reasonable fears, or the small fears. All. Every single one. The key was seeking — actively pursuing God rather than passively waiting for fear to pass. When you seek God in your anxiety, He doesn't just manage your symptoms. He delivers you. Not always instantly, but completely. Seek Him today, and trust Him for deliverance.",
            prayerText: "Lord, I seek You right now — not as a last resort, but as my first response. Deliver me from all my fears. Not just the big ones — all of them. The fears I'm ashamed of, the fears I've named, and the ones lurking beneath the surface. You answered David, and I trust You'll answer me. In Jesus' name, amen.",
            reflectionPrompt: "Are you seeking God as your first response to anxiety or your last resort?",
            actionSteps: ["List every fear you can think of and pray over each one, asking God for deliverance", "Make seeking God your first action tomorrow morning before checking your phone"]
        ),
        DayContent(
            scriptureReference: "Romans 8:38-39",
            scriptureText: "For I am convinced that neither death nor life, neither angels nor demons, neither the present nor the future, nor any powers, neither height nor depth, nor anything else in all creation, will be able to separate us from the love of God that is in Christ Jesus our Lord.",
            devotionalTitle: "Nothing Can Separate You",
            devotionalText: "Anxiety's deepest fear is separation — being alone, abandoned, forgotten. Paul demolishes that fear with one of the most sweeping promises in Scripture. He lists every category of threat and declares: none of them can separate you from God's love. Not your present struggles. Not your future unknowns. Not any power, seen or unseen. You are permanently, irrevocably loved.",
            prayerText: "Lord, I am convinced — nothing can separate me from Your love. Not my anxiety, not my failures, not my darkest moments. Not the present, not the future, not anything in all creation. Your love holds me, and nothing can pry me loose. Let this truth sink deeper than my deepest fear. I am loved, and I am Yours. In Jesus' name, amen.",
            reflectionPrompt: "What has anxiety told you could separate you from God's love? How does this verse answer that lie?",
            actionSteps: ["Memorize Romans 8:38-39 and recite it when anxiety tells you you're alone", "Write 'Nothing can separate me' on your mirror or phone background"]
        ),
        DayContent(
            scriptureReference: "Proverbs 12:25",
            scriptureText: "Anxiety weighs down the heart, but a kind word cheers it up.",
            devotionalTitle: "The Weight of Worry",
            devotionalText: "Solomon understood that anxiety is physical — it literally weighs down your heart. But the remedy he offers is surprisingly simple: a kind word. Sometimes the most powerful thing you can do for your anxiety is receive encouragement from someone who cares. And sometimes the best medicine for your own worry is offering kindness to someone else. Connection lightens what isolation makes heavy.",
            prayerText: "Lord, my heart feels heavy today. Lift the weight of anxiety through Your kindness and the kindness of others. Send me encouraging words, and help me be an encourager too. Break the isolation that anxiety builds. Remind me that I was made for connection, not for carrying heavy loads alone. Cheer my heart today. In Jesus' name, amen.",
            reflectionPrompt: "Whose kind word has cheered your anxious heart recently? Have you told them?",
            actionSteps: ["Reach out to someone you trust and ask for encouragement", "Send a kind, encouraging message to someone who might be struggling with anxiety"]
        ),
    ]
}
